package terraform

import (
	"log"
	"strings"

	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/configs"
	"github.com/hashicorp/terraform/internal/dag"
)

// GraphNodeAttachResourceConfig is an interface that must be implemented by nodes
// that want resource configurations attached.
type GraphNodeAttachResourceConfig interface {
	GraphNodeConfigResource

	// Sets the configuration, either to a present resource block or to
	// a "removed" block commemorating a resource that has since been
	// removed. Callers should always leave at least one of these
	// arguments set to nil.
	AttachResourceConfig(*configs.Resource, *configs.Removed)
}

// AttachResourceConfigTransformer goes through the graph and attaches
// resource configuration structures to nodes that implement
// GraphNodeAttachManagedResourceConfig or GraphNodeAttachDataResourceConfig.
//
// The attached configuration structures are directly from the configuration.
// If they're going to be modified, a copy should be made.
type AttachResourceConfigTransformer struct {
	Config *configs.Config // Config is the root node in the config tree
}

func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {
	for _, v := range g.Vertices() {
		arn, ok := v.(GraphNodeAttachResourceConfig)
		if !ok {
			continue
		}

		addr := arn.ResourceAddr()
		vertexName := dag.VertexName(v)
		res := addr.Resource
		resType := res.Type
		resName := res.Name

		var modulePath strings.Builder
		modulePath.Grow(len(addr.Module) * 16)
		modSep := ""
		for _, step := range addr.Module {
			modulePath.WriteString(modSep)
			modulePath.WriteString("module.")
			modulePath.WriteString(step)
			modSep = "."
		}
		modulePathStr := modulePath.String()

		config := t.Config
		for _, step := range addr.Module {
			config = config.Children[step]
			if config == nil {
				break
			}
		}

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", vertexName, v)
			continue
		}

		mod := config.Module
		managedResources := mod.ManagedResources
		dataResources := mod.DataResources
		providerMetas := mod.ProviderMetas
		removedBlocks := mod.Removed

		var lookupKey strings.Builder
		lookupKey.Grow(len(resType) + len(resName) + 6)
		var resourceCfg *configs.Resource
		if res.Mode == addrs.ManagedResourceMode {
			lookupKey.WriteString(resType)
			lookupKey.WriteByte('.')
			lookupKey.WriteString(resName)
			resourceCfg = managedResources[lookupKey.String()]
		} else if res.Mode == addrs.DataResourceMode {
			lookupKey.WriteString("data.")
			lookupKey.WriteString(resType)
			lookupKey.WriteByte('.')
			lookupKey.WriteString(resName)
			resourceCfg = dataResources[lookupKey.String()]
		}
		lookupKeyStr := lookupKey.String()
		log.Printf("[TRACE] AttachResourceConfigTransformer: resolving %q module %q key %q", vertexName, modulePathStr, lookupKeyStr)

		if resourceCfg != nil {
			declRange := resourceCfg.DeclRange
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", vertexName, v, declRange)
			arn.AttachResourceConfig(resourceCfg, nil)
			if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", vertexName)
				if providerMetas != nil {
					gnapmc.AttachProviderMetaConfigs(providerMetas)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", vertexName)
				}
			}
		}

		for _, removedBlock := range removedBlocks {
			from := removedBlock.From
			var crAddr addrs.ConfigResource
			switch subj := from.RelSubject.(type) {
			case addrs.Module:
				continue
			case addrs.ConfigResource:
				crAddr = subj
			default:
				continue
			}

			removedRes := crAddr.Resource
			if removedRes != res {
				continue
			}

			removedDecl := removedBlock.DeclRange
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", vertexName, v, removedDecl)
			arn.AttachResourceConfig(nil, removedBlock)
		}
	}

	return nil
}

